import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import Popup from "./Popup";
import axios from "axios";
import { Group } from "../Model/Group.model";
import "./styles/Groups.scss";
import GroupNavBar from "./GroupNavBar";
import { APIService } from "../api/requests";
import {
  Button,
  Checkbox,
  Container,
  createTheme,
  Flex,
  MantineProvider,
  Paper,
} from "@mantine/core";
import { IconTrash, IconUsersGroup } from "@tabler/icons-react";
import { group } from "console";
import { setgroups } from "process";

function Groups() {
  const navigate = useNavigate();
  const [groups, setGroups] = useState<Group[]>([]);
  const [showPopup, setShowPopup] = useState<boolean>(false);
  const [showDelete, setShowDelete] = useState(false);
  const [DeleteAll, setDeleteAll] = useState(false);
  let [selectedItems, setCount] = useState(0);

  const theme = createTheme({
    cursorType: "pointer",
  });

  useEffect(() => {
    setCount(0);
    axios
      .get<Group[]>(`http://localhost:5257/api/Group/`)
      .then((response) => {
        const newGroups = response.data.map((group) => {
          return { ...group, isChecked: false };
        });
        setGroups(newGroups);
      })
      .catch((error) => {
        console.log(error);
      });
  }, []);

  const openGroup = (event: any, groupId: string) => {
    event?.stopPropagation();
    navigate(`/group/${groupId}`);
  };
  const handleOpenPopup = () => {
    setShowPopup(true);
  };

  const handleClosePopup = () => {
    setShowPopup(false);
  };

  const handleSelection = (isChecked: boolean, Id: string) => {
    setShowDelete(isChecked);
    if (isChecked) {
      setCount(++selectedItems);
    } else {
      setCount(--selectedItems);
    }
  };

  const onCreate = (value: string) => {
    if (value.trim().length === 0) {
      return;
    }
    APIService.group.postGroup({ name: value }).then((response) => {
      setGroups((old) => [...old, response.data]);
    });
  };

  const checkHandler = (idToUpdate: string, checked: boolean) => {
    const group = groups.find((x) => x.id === idToUpdate);
    if (group != null) {
      const updatedGroups = groups.map((x) =>
        x.id === idToUpdate ? { ...x, isChecked: checked } : x
      );

      setGroups(updatedGroups);
      const count = updatedGroups.filter((x) => x.isChecked).length;
      if (count > 0) setShowDelete(true);
      else setShowDelete(false);

      if (count === groups.length) {
        setDeleteAll(true);
      } else setDeleteAll(false);
    }
  };
  const checkAll = (state: boolean) => {
   const updatedGroups = groups.map((group) => ({
    ...group,
    isChecked: state,
  }));

  setGroups(updatedGroups);

  const count = updatedGroups.filter((x) => x.isChecked).length;

  // setShowDelete is true if at least one item is checked
  setShowDelete(count > 0);

  // setDeleteAll is true only if ALL items are checked
  setDeleteAll(count === updatedGroups.length);
  };
  return (
    <>
      <Paper shadow="xs">
        <GroupNavBar handlePopup={handleOpenPopup} />
      </Paper>
      <Popup
        show={showPopup}
        onClose={handleClosePopup}
        title="Enter new group name"
        onSubmit={(name) => onCreate(name)}
      />
      <Container size="lg" w="90%">
        <Flex
          bg="white"
          justify="space-between"
          align="center"
          pt="xs"
          pb="xs"
          p="sm"
          style={{ borderTopLeftRadius: "20px", borderTopRightRadius: "20px" }}
          mt="md"
        >
          <MantineProvider theme={theme}>
            <Checkbox
              size="sm"
              me="sm"
              label="Select All"
              checked={DeleteAll}
              onChange={(e) => checkAll(e.target.checked)}
            ></Checkbox>
          </MantineProvider>

          <Button
            color="red"
            radius="20px"
            className={showDelete ? "button show" : "button"}
          >
            <IconTrash size="20" className="me-1" />
            Delete Selected
          </Button>
        </Flex>
        {/* Group section */}
        {groups.map((group) => (
          <Flex align="flex-start" bg="white" p="sm" className="shadow">
            <MantineProvider theme={theme}>
              <Checkbox
                size="sm"
                me="sm"
                checked={group.isChecked}
                onChange={(e) => checkHandler(group.id, e.target.checked)}
              ></Checkbox>
            </MantineProvider>
            <IconUsersGroup className="me-3" />
            <Flex direction="column" justify="space-between">
              <div className="d-flex fw-semibold">{group.name}</div>
              <div className="small text-muted">
                24 members •
                <span className="text-danger">Owe: {group.totalOwe}</span> •
                <span className="text-success">Owed: {group.totalOwed}</span> •
                Created
              </div>
            </Flex>

            <div className="d-flex align-items-end justify-content-end ms-auto p-2"></div>
          </Flex>
        ))}
      </Container>
    </>
  );
}

export default Groups;
